from pathlib import Path

def export_report(rows: list[dict], destination: Path) -> None:
    with destination.open("w", encoding="utf-8") as stream:
        for row in rows:
            stream.write(f"{row['id']},{row['amount']}\n")
            if row["amount"] < 0:
                raise ValueError(f"Montant négatif pour {row['id']}")
    # même si l'exception interrompt la boucle, le fichier est fermé proprement
